// src/helpers/format-media-duration.ts
var formatMediaDuration = (seconds) => {
  const h = Math.floor(seconds / 3600);
  const m = Math.floor(seconds % 3600 / 60);
  const s = seconds % 60;
  const sFixed = s.toFixed(2).padStart(5, "0");
  if (h > 0) {
    return `${h}:${String(m).padStart(2, "0")}:${sFixed}`;
  }
  return `${String(m).padStart(2, "0")}:${sFixed}`;
};

// src/helpers/get-preview-file-type.ts
var getPreviewFileType = (fileName) => {
  if (!fileName) {
    return "other";
  }
  const audioExtensions = ["mp3", "wav", "ogg", "aac", "m4a", "flac"];
  const videoExtensions = [
    "mp4",
    "avi",
    "mkv",
    "mov",
    "webm",
    "m4v",
    "ts",
    "m2ts",
    "m3u8"
  ];
  const imageExtensions = [
    "jpg",
    "jpeg",
    "png",
    "apng",
    "gif",
    "bmp",
    "webp",
    "svg"
  ];
  const fontExtensions = ["woff", "woff2", "ttf", "otf", "eot"];
  const fileExtension = fileName.split(".").pop()?.toLowerCase();
  if (fileExtension === undefined) {
    throw new Error("File extension is undefined");
  }
  if (audioExtensions.includes(fileExtension)) {
    return "audio";
  }
  if (videoExtensions.includes(fileExtension)) {
    return "video";
  }
  if (imageExtensions.includes(fileExtension)) {
    return "image";
  }
  if (fontExtensions.includes(fileExtension)) {
    return "font";
  }
  if (fileExtension === "json") {
    return "json";
  }
  if (fileExtension === "cube") {
    return "lut";
  }
  if (fileExtension === "txt") {
    return "txt";
  }
  return "other";
};

